-- Rodos Atlantic A001–A006: точні кольори, види полотна й фото з офіційних карток Rodos.
-- Скрипт не змінює інші колекції або бренди. Кожна модель очищається тільки перед повторним наповненням її конфігуратора.
do $$ begin if (select count(*) from public.products where slug in ('rodos-official-1osu0nc','rodos-official-16d044a','rodos-official-bf2ks0','rodos-official-1osu0nj','rodos-official-lnsyln')) <> 5 then raise exception 'Не знайдено всі моделі Atlantic для пакета — каталог не змінено'; end if; end $$;
begin;
delete from public.product_options where product_slug = 'rodos-official-1osu0nc';
delete from public.product_variants where product_slug = 'rodos-official-1osu0nc';
delete from public.product_media where product_slug = 'rodos-official-1osu0nc' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-16d044a';
delete from public.product_variants where product_slug = 'rodos-official-16d044a';
delete from public.product_media where product_slug = 'rodos-official-16d044a' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-bf2ks0';
delete from public.product_variants where product_slug = 'rodos-official-bf2ks0';
delete from public.product_media where product_slug = 'rodos-official-bf2ks0' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-1osu0nj';
delete from public.product_variants where product_slug = 'rodos-official-1osu0nj';
delete from public.product_media where product_slug = 'rodos-official-1osu0nj' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-lnsyln';
delete from public.product_variants where product_slug = 'rodos-official-lnsyln';
delete from public.product_media where product_slug = 'rodos-official-lnsyln' and label like 'config:%';
commit;
select product_slug, count(*) filter (where option_group = 'color') as кольорів, count(*) filter (where option_group = 'configuration') as видів_полотна from public.product_options where product_slug in ('rodos-official-1osu0nf','rodos-official-1osu0nc','rodos-official-16d044a','rodos-official-bf2ks0','rodos-official-1osu0nj','rodos-official-lnsyln') group by product_slug order by product_slug;